import { useEffect, useRef, useState } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { formatElapsed } from '../elapsed-time.ts';
import { createGame, isWon } from '../game.ts';
import { decodeSnapshot } from '../snapshot.ts';
import { activateSession, initialSession, replaceGame } from '../session/session.ts';
import type { Session } from '../session/session.ts';
import { useSessionClock } from '../session/use-session-clock.ts';
import { GameStatus } from '../status/GameStatus.tsx';
import {
  createTournament,
  currentMatch,
  currentPlayer,
  exportTournament,
  importTournament,
  nameError,
  nextMatch,
  normalizeName,
  recordResult,
  roundName,
} from './tournament.ts';
import type { Tournament as TournamentState } from './tournament.ts';
import './tournament.css';

const HISTORY_KEY = 'neon-pairs.tournaments.v1';
function readHistory(): TournamentState[] {
  try {
    const data: unknown = JSON.parse(localStorage.getItem(HISTORY_KEY) ?? '[]');
    if (!Array.isArray(data)) return [];
    return data.flatMap((item: unknown) => {
      const decoded = importTournament(JSON.stringify(item));
      return decoded.tournament?.phase === 'champion' ? [decoded.tournament] : [];
    });
  } catch {
    return [];
  }
}
function saveHistory(history: TournamentState[]): void {
  try {
    localStorage.setItem(
      HISTORY_KEY,
      JSON.stringify(history.map((t) => JSON.parse(exportTournament(t)))),
    );
  } catch {
    /* Storage is optional. */
  }
}

export function Tournament({ back }: { back(): void }) {
  const [count, setCount] = useState(4);
  const [names, setNames] = useState(Array<string>(8).fill(''));
  const [t, setTournament] = useState<TournamentState | null>(null);
  const [history, setHistory] = useState(readHistory);
  const [draft, setDraft] = useState('');
  const [notice, setNotice] = useState('');
  const [confirmAction, setConfirmAction] = useState<(() => void) | null>(null);
  const heading = useRef<HTMLHeadingElement>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const keep = useRef<HTMLButtonElement>(null);
  const board = useRef<BoardFocus>(null);
  const [session, setSession] = useState(() =>
    initialSession('np1-4-1', { size: 4, bestMoves: {} }),
  );
  const current = useRef(session);
  function commit(next: Session): void {
    current.current = next;
    setSession(next);
  }
  const clock = useSessionClock(session, current, commit);
  useEffect(() => {
    heading.current?.focus();
  }, [t?.phase, t?.round, t?.match]);
  useEffect(() => {
    if (confirmAction) {
      dialog.current?.showModal();
      keep.current?.focus();
    }
  }, [confirmAction]);
  function leave(action: () => void): void {
    if (t && t.phase !== 'champion') setConfirmAction(() => action);
    else action();
  }
  function start(): void {
    const clean = names.slice(0, count).map(normalizeName);
    const error = nameError(clean);
    if (error) {
      setNotice(error);
      return;
    }
    setNotice('');
    setTournament(createTournament(clean));
  }
  function startTurn(): void {
    if (!t) return;
    if (t.phase === 'playing' && current.current.paused) {
      clock.reset();
      commit({ ...current.current, paused: false });
      board.current?.focusRemembered();
      return;
    }
    setNotice('');
    clock.reset();
    const next = replaceGame(current.current, createGame(currentMatch(t).code), false);
    commit(next);
    setTournament({ ...t, phase: 'playing', game: null });
  }
  function activate(index: number): void {
    if (!t || t.phase !== 'playing') return;
    clock.synchronize();
    // Competition sessions deliberately retain the solo-independent preference object.
    const previous = current.current;
    const next = activateSession(previous, index);
    commit({ ...next, preferences: previous.preferences });
    if (!isWon(previous.game) && isWon(next.game)) {
      const updated = recordResult(t, next.game);
      setTournament(updated);
      setNotice(
        updated.phase === 'turnDone'
          ? `${t.names[currentPlayer(t)]} finished in ${next.game.moves} moves and ${formatElapsed(next.game.elapsedMs)}.`
          : `${t.names[currentMatch(updated).winner!]} wins the match.`,
      );
      if (updated.phase === 'champion') {
        const nextHistory = [updated, ...history];
        setHistory(nextHistory);
        saveHistory(nextHistory);
      }
    }
  }
  function load(): void {
    try {
      const value: unknown = JSON.parse(draft);
      if (value && typeof value === 'object' && !Array.isArray(value)) {
        const object = value as Record<string, unknown>;
        if (
          Object.keys(object).length === 3 &&
          object.format === 'neon-pairs/tournament' &&
          object.version === 1 &&
          object.tournament === null
        ) {
          leave(() => {
            setTournament(null);
            setNotice('Tournament loaded.');
          });
          return;
        }
      }
    } catch {
      /* The tournament decoder supplies the error. */
    }
    const result = importTournament(draft);
    if (!result.tournament) {
      setNotice(result.error);
      return;
    }
    const loaded = result.tournament;
    leave(() => {
      if (loaded.phase === 'playing') {
        const game = decodeSnapshot(loaded.game!);
        if (!game) return;
        clock.reset();
        commit(replaceGame(current.current, game, true));
      }
      setTournament(loaded);
      setNotice('Tournament loaded.');
    });
  }
  function exportCurrent(): void {
    if (!t) {
      setDraft(
        JSON.stringify({ format: 'neon-pairs/tournament', tournament: null, version: 1 }, null, 2),
      );
      setNotice('Start or select a tournament to export its results.');
      return;
    }
    clock.synchronize();
    setDraft(exportTournament(t, current.current.game));
    setNotice('Tournament exported.');
  }
  return (
    <section className="tournament">
      <h2 ref={heading} tabIndex={-1}>
        Tournament
      </h2>
      <div className="game-result">
        <p role="status" aria-live="polite" aria-atomic="true">
          <span key={notice || session.announcement}>
            {notice || (t?.phase === 'playing' ? session.feedback : '')}
          </span>
        </p>
      </div>
      {!t ? (
        <>
          <div className="tournament-form">
            <label htmlFor="players">Players</label>
            <select
              className="control"
              id="players"
              value={count}
              onChange={(e) => setCount(Number(e.currentTarget.value))}
            >
              <option value={4}>4</option>
              <option value={8}>8</option>
            </select>
            {names.slice(0, count).map((name, i) => (
              <div className="name-field" key={i}>
                <label htmlFor={`player-${i}`}>Player {i + 1}</label>
                <input
                  className="control"
                  id={`player-${i}`}
                  value={name}
                  onChange={(e) => {
                    const values = [...names];
                    values[i] = e.currentTarget.value;
                    setNames(values);
                  }}
                />
              </div>
            ))}
            <button className="control" type="button" onClick={start}>
              Start tournament
            </button>
            <button className="control" type="button" onClick={back}>
              Back to game
            </button>
          </div>
          <h3>Past tournaments</h3>
          {history.length === 0 ? (
            <p>None yet.</p>
          ) : (
            <ul>
              {history.map((past, i) => (
                <li key={i}>
                  <button
                    className="control"
                    type="button"
                    onClick={() => {
                      setTournament(past);
                      setNotice('');
                    }}

                    }}
                  >
                    Champion: {past.names[currentMatch(past).winner!]}
                  </button>
                </li>
              ))}
            </ul>
          )}
        </>
      ) : (
        <>
          {t.phase === 'champion' ? (
            <>
              <p className="victory">Champion: {t.names[currentMatch(t).winner!]}</p>
              <button className="control" type="button" onClick={back}>
                Back to game
              </button>
              <button className="control" type="button" onClick={() => setTournament(null)}>
                Tournament screen
              </button>
            </>
          ) : (
            <>
              <p>Round: {roundName(t.rounds[t.round]!.length)}</p>
              <p>Now playing: {t.names[currentPlayer(t)]}</p>
              {(t.phase === 'ready' || (t.phase === 'playing' && session.paused)) && (
                <button className="control" type="button" onClick={startTurn}>
                  Start turn
                </button>
              )}
              {t.phase === 'turnDone' && (
                <button
                  className="control"
                  type="button"
                  onClick={() => {
                    setTournament({ ...t, phase: 'ready' });
                    setNotice(`Now playing: ${t.names[currentPlayer(t)]}`);
                  }}
                >
                  Next turn
                </button>
              )}
              {t.phase === 'matchDone' && (
                <button
                  className="control"
                  type="button"
                  onClick={() => {
                    const next = nextMatch(t);
                    setTournament(next);
                    setNotice(`Now playing: ${next.names[currentPlayer(next)]}`);
                  }}
                >
                  Next match
                </button>
              )}
              <button className="control" type="button" onClick={() => leave(back)}>
                Leave tournament
              </button>
              {t.phase === 'playing' && (
                <>
                  <GameStatus
                    game={session.game}
                    best={undefined}
                    celebration={session.celebration}
                  />
                  <p id="board-help" className="help">
                    Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or
                    Space reveals a card.
                  </p>
                  <Board
                    key={session.generation}
                    game={session.game}
                    activate={activate}
                    ref={board}
                  />
                </>
              )}
            </>
          )}
          <h3>Bracket</h3>
          {t.rounds.map((round, r) => (
            <div key={r}>
              <h4>{roundName(round.length)}</h4>
              <div className="tournament-table">
                <table>
                  <caption>{roundName(round.length)} matches</caption>
                  <thead>
                    <tr>
                      <th scope="col">Match</th>
                      <th scope="col">Player</th>
                      <th scope="col">Moves</th>
                      <th scope="col">Time</th>
                      <th scope="col">Winner</th>
                    </tr>
                  </thead>
                  <tbody>
                    {round.flatMap((m, i) =>
                      m.players.map((player, p) => (
                        <tr key={`${i}-${p}`}>
                          <td>{i + 1}</td>
                          <th scope="row">{t.names[player]}</th>
                          <td>{m.results[p]?.moves ?? '—'}</td>
                          <td>{m.results[p] ? formatElapsed(m.results[p]!.elapsedMs) : '—'}</td>
                          <td>{m.winner === player ? t.names[player] : '—'}</td>
                        </tr>
                      )),
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          ))}
          {t.rounds.at(-1)!.length > 1 &&
            Array.from({ length: Math.log2(t.rounds.at(-1)!.length) }, (_, index) => {
              const matches = t.rounds.at(-1)!.length / 2 ** (index + 1);
              return (
